use crate::wasi::clocks::wall_clock;

struct Node;

/// Last day representable as a 4-digit year: 9999-12-31, as days since 1970-01-01.
const MAX_DAYS: u64 = 2_932_896;

/// Convert days since the Unix epoch to a (year, month, day) civil date.
/// Howard Hinnant's `civil_from_days` algorithm.
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as u64; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    (if m <= 2 { y + 1 } else { y }, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // Note: the requested input logging and metadata enrichment are not
        // performed. This node holds only wasi:clocks/wall-clock; it has no
        // filesystem and no HTTP capability.
        let now = wall_clock::now();
        let started = now.seconds;

        // Clamp so the year always has exactly four digits, keeping len(date) == 10.
        let days = (started / 86_400).min(MAX_DAYS) as i64;
        let (y, m, d) = civil_from_days(days);
        let y = y.clamp(1970, 9999);

        let date = format!("{:04}-{:02}-{:02}", y, m, d);

        RunInfo { date, started }
    }
}

export!(Node);
```

